package com.wansheng.visitor.guard;
import com.fasterxml.jackson.databind.*;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component class GuardOaStatusConsumer{private final ObjectMapper json;private final RestClient client;private final GuardRepository repo;private final String url,token;GuardOaStatusConsumer(ObjectMapper j,RestClient.Builder b,GuardRepository r,@Value("${visitor.guard.registration-service-url}")String u,@Value("${visitor.guard.internal-token}")String t){json=j;client=b.build();repo=r;url=u;token=t;}@RabbitListener(queues="guard.oa-approval-updated")void receive(String p)throws Exception{String vid=json.readTree(p).path("visitId").asText();GuardRegistrationConsumer.GuardView v=client.get().uri(url+"/internal/registrations/{id}/guard-view",vid).header("X-Internal-Token",token).retrieve().body(GuardRegistrationConsumer.GuardView.class);repo.updateOaStatus(vid,v.oaStatus());}}
